export type StyleBestForEntry = {
  /** Occasion / use-case phrases, e.g. "Diwali, festive Instagram posts". */
  readonly occasions: string;
  /** Suitable input photo type, e.g. "solo portrait, half or full body photo". */
  readonly worksWith: string;
};

export type StyleBestForLine = StyleBestForEntry & {
  readonly line: string;
};

