function haystackFor(style: CatalogStyle, extraText = ""): string {
  return [
    style.id,
    style.title,
    style.category,
    style.note,
    style.description,
    style.targetSourcePhoto,
    extraText,
  ]
    .join("\n")
    .toLowerCase();
}

function isFestiveStyle(hay: string): boolean {
  // Only the style’s own catalog text — not guide membership — decides festive.
  return FESTIVE_OCCASION_WORDS.test(hay);
}

function isFestiveOccasionLabel(value: string): boolean {
  return /\b(Diwali|Christmas|Halloween|festive|holiday|costume|Eid)\b/i.test(
    value,
  );
}

function collectOccasions(
  style: CatalogStyle,
  guideSlugs: readonly string[],
): string[] {
  // Occasion labels come from the style’s own catalog fields + guide
  // membership — not from long uniqueness FAQs (those cross-link other looks
  // and would leak festive/outfit occasions onto unrelated pages).
  const hay = haystackFor(style);
  const festive = isFestiveStyle(hay);
  const ordered: string[] = [];
  const seen = new Set<string>();

  const pushAll = (values: readonly string[]) => {
    for (const value of values) {
      if (seen.has(value)) continue;
      // Never attach festive occasions to non-festive styles.
      if (!festive && isFestiveOccasionLabel(value)) continue;
      seen.add(value);
      ordered.push(value);
    }
  };

  for (const slug of guideSlugs) {
    const fromGuide = GUIDE_OCCASIONS[slug];
    if (!fromGuide) continue;
    // Festive guide membership only contributes festive labels when the style
    // itself is festive (cross-links in festival guides are common).
    if (!festive && fromGuide.some(isFestiveOccasionLabel)) continue;
    pushAll(fromGuide);
  }

  for (const rule of TITLE_OCCASION_RULES) {
    if (rule.festive && !festive) continue;
    if (rule.match(hay)) pushAll(rule.occasions);
  }

  if (ordered.length === 0) {
    if (style.category === "Professional portraits") {
      pushAll(["Professional headshots", "profile photos"]);
    } else if (style.category === "Product and objects") {
      pushAll(["Product listings", "shop galleries"]);
    } else if (style.category === "Pets" || style.subject === "Pet") {
      pushAll(["Pet portraits", "social posts"]);
    } else if (style.category === "Anime") {
      pushAll(["Anime-style edits", "stylized portraits"]);
    } else if (style.category === "Travel") {
      pushAll(["Travel edits", "vacation posts"]);
    } else if (style.subject === "Group" || style.category === "Couple") {
      pushAll(["Couple or group posts"]);
    } else {
      pushAll(["Social portraits", "Instagram posts"]);
    }
  }

  // Drop people-portrait guide labels that do not fit product/pet subjects.
  const coherent = ordered.filter((value) => {
    if (style.category === "Product and objects" || style.subject === "Product or object") {
      return !/\b(Instagram portraits|boy edits|couple|bridal|headshots|Anime-style)\b/i.test(
        value,
      );
    }
    if (style.subject === "Pet" || style.category === "Pets") {
      return !/\b(boy edits|couple|bridal|headshots|Outfit change|LinkedIn)\b/i.test(
        value,
      );
    }
    return true;
  });

  if (coherent.length === 0) {
    if (style.category === "Product and objects" || style.subject === "Product or object") {
      return ["Product listings", "shop galleries"];
    }
    if (style.subject === "Pet" || style.category === "Pets") {
      return ["Pet portraits", "social posts"];
    }
  }

  return coherent.slice(0, 3);
}

function isTwoPhotoMerge(style: CatalogStyle): boolean {
  if (style.requirement === "Two photos" || style.promptVariant.inputImageCount >= 2) {
    return true;
  }
  // Some merge looks are catalogued as one upload slot but still ask for two
  // portraits in targetSourcePhoto (e.g. separate-photos-couple).
  const target = style.targetSourcePhoto.toLowerCase();
  return (
    /\btwo (clear )?(individual |separate )?photos?\b/.test(target) ||
    /\btwo (clear )?(individual |separate )?portraits?\b/.test(target)
  );
}

/**
 * Short input-photo line. Couple/family phrasing is reserved for merge/two-photo
 * styles and for one-photo styles whose target is explicitly a couple/group frame.
 */
export function worksWithForStyle(style: CatalogStyle): string {
  const hay = haystackFor(style);
  const merge = isTwoPhotoMerge(style);
  const target = style.targetSourcePhoto.toLowerCase();

  if (merge) {
    if (/\bpet\b|\bdog\b|\bcat\b/.test(hay)) {
      return "two photos (person + pet merge)";
    }
    if (/\bfamily\b/.test(hay) || style.subject === "Group") {
      if (/\bfriend|\bgroup\b|\bsquad\b/.test(hay)) {
        return "two or more separate portraits (group merge)";
      }
      return "two separate portraits (family or couple merge)";
    }
    if (/\bcouple\b|\bpartners\b/.test(hay) || style.category === "Couple") {
      return "two separate portraits (couple merge)";
    }
    return "two separate portraits (merge)";
  }

  // One-photo paths — keep photo type honest to targetSourcePhoto / subject.
  if (style.subject === "Pet" || /\bpet portrait\b|\bdog\b|\bcat\b/.test(target)) {
    return "clear pet photo";
  }
  if (style.subject === "Place") return "clear place or landmark photo";
  if (style.subject === "Product or object" || style.category === "Product and objects") {
    return "clear product photo";
  }

  if (
    /\bcouple\b/.test(target) ||
    (/\bcouple\b/.test(hay) && style.subject === "Group")
  ) {
    return "couple portrait (one frame)";
  }
  if (/\bfamily\b|\bgroup\b/.test(target) || style.subject === "Group") {
    if (/\bfamily\b/.test(hay)) return "family group photo";
    return "group photo with every face visible";
  }

  if (/\bhead-and-shoulders\b|\bheadshot\b|\bpassport\b|\blinkedin\b/.test(target + hay)) {
    return "solo headshot or selfie";
  }
  if (/\bfull-length\b|\bfull body\b|\bfull-body\b/.test(target)) {
    return "solo portrait, full body photo";
  }
  if (/\bwaist-up\b|\bthree-quarter\b|\bhalf\b|\bchest-up\b/.test(target)) {
    return "solo portrait, half or three-quarter body photo";
  }
  if (/\bselfie\b/.test(target + hay)) return "clear solo selfie";

  return "solo portrait, half or full body photo";
}

export function buildStyleBestFor(
  style: CatalogStyle,
  options?: {
    guideSlugs?: readonly string[];
  },
): StyleBestForLine {
  const guideSlugs = options?.guideSlugs ?? [];
  const occasionsList = collectOccasions(style, guideSlugs);
  const occasions = occasionsList.join(", ");
  const worksWith = worksWithForStyle(style);
  return {
    occasions,
    worksWith,
    line: `Best for: ${occasions} · Works with: ${worksWith}`,
  };
}

export function formatBestForLine(entry: StyleBestForEntry): string {
  return `Best for: ${entry.occasions} · Works with: ${entry.worksWith}`;
}

export function renderStyleBestForFile(
  entries: Readonly<Record<string, StyleBestForEntry>>,
): string {
  const body = Object.keys(entries)
    .sort((a, b) => a.localeCompare(b))
    .map((id) => {
      const entry = entries[id]!;
      return `  ${JSON.stringify(id)}: {
    occasions: ${JSON.stringify(entry.occasions)},
    worksWith: ${JSON.stringify(entry.worksWith)},
  },`;
    })
    .join("\n");

  return `// Generated by writeStyleBestForData(). Do not edit.
import type { StyleBestForEntry } from "./style-best-for";

export const STYLE_BEST_FOR: Readonly<Record<string, StyleBestForEntry>> = {
${body}
};
`;
}

/** Build + write best-for lines for every published seed style. */
export function writeStyleBestForData(
  styles: readonly CatalogStyle[],
  options?: {
    membership?: Readonly<Record<string, readonly string[]>>;
  },
): Record<string, StyleBestForEntry> {
  const membership = options?.membership ?? {};
  const entries: Record<string, StyleBestForEntry> = {};
  for (const style of styles) {
    const built = buildStyleBestFor(style, {
      guideSlugs: membership[style.id] ?? [],
    });
    entries[style.id] = {
      occasions: built.occasions,
      worksWith: built.worksWith,
    };
  }
  const next = renderStyleBestForFile(entries);
  const current = fs.existsSync(STYLE_BEST_FOR_PATH)
    ? fs.readFileSync(STYLE_BEST_FOR_PATH, "utf8")
    : "";
  if (current !== next) fs.writeFileSync(STYLE_BEST_FOR_PATH, next);
  return entries;
}
